//! Language names (#244): what the app calls a Resource's language tag (`bn`, `kmo`,
//! `zh-Hant`, `cop-sa`), in English and, where known, in the language itself, so no list shows
//! a bare code.
//!
//! The names are built in (`assets/languages/`, regenerated by `cargo xtask language-names`):
//! - Unicode CLDR's English names of languages, scripts and regions, and each language's name
//!   in its own locale (`bn` is "Bangla", "বাংলা");
//! - the ISO 639-3 code tables (SIL International): the reference name of every code CLDR does
//!   not name (`kmo` is "Kwoma"), which ISO 639-1, 639-2/B and 639-3 codes are one language
//!   (`ben` is `bn`), and what became of retired codes (eBible.org still tags Bibles `daf`).
//!
//! A tag is read as BCP 47 (`language[-Script][-REGION][-variant…]`, any case, `_` allowed),
//! which is what SWORD confs' `Lang=` holds, except for a few SWORD tags that name a dialect
//! with a subtag BCP 47 would read as a region ([`SWORD_TAGS`]).

use std::collections::HashMap;
use std::sync::OnceLock;

const CLDR_NAMES: &str = include_str!("../assets/languages/cldr-names.tsv");
const ISO_639_3: &str = include_str!("../assets/languages/iso-639-3.tsv");

/// SWORD `Lang=` values that are not BCP 47: CrossWire writes Sahidic Coptic as `cop-sa`, which
/// BCP 47 would read as Coptic of Saudi Arabia.
const SWORD_TAGS: &[(&str, &str)] = &[
    ("cop-sa", "Coptic (Sahidic)"),
    ("cop-bo", "Coptic (Bohairic)"),
];

/// A language tag's names, and what a search for it matches.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct LanguageName {
    /// The tag as the Resource gives it.
    pub tag: String,
    /// The English name ("Bangla", "Serbian (Latin)", "Kwoma"); `None` for a tag no table
    /// knows.
    pub english: Option<String>,
    /// The name in the language itself ("বাংলা"), when CLDR has it and it differs from the
    /// English one.
    pub native: Option<&'static str>,
    /// Other English names a search finds: CLDR's alternatives and the ISO 639-3 reference
    /// name ("Bengali").
    pub also: Vec<&'static str>,
    /// The tag (lower case) and every code of its language: ISO 639-1, 639-2/B and 639-3
    /// (`bn`, `ben`).
    pub codes: Vec<String>,
    /// The language subtag, as ISO 639-1 where it has one (`bn` for `ben-IN`).
    pub primary: String,
    /// The tag as the names read it: ISO 639-1 where there is one, BCP 47 case, without the
    /// script the language is usually written in. `ben-Beng-IN` and `bn-IN` are both `bn-IN`,
    /// `en-Latn` and `EN` both `en`; tags with one key are one language.
    pub key: String,
    /// Every name, lower case, for [`Self::matches`].
    lower_names: Vec<String>,
}

/// The names of `tag`.
pub fn language(tag: &str) -> LanguageName {
    tables().name(tag)
}

impl LanguageName {
    /// Whether a table names the tag.
    pub fn is_known(&self) -> bool {
        self.english.is_some()
    }

    /// The English name, or "Unknown language (xyz)".
    pub fn english_label(&self) -> String {
        match &self.english {
            Some(e) => e.clone(),
            None => format!("Unknown language ({})", self.tag.trim()),
        }
    }

    /// "Bangla — বাংলা": the English name, then the name in the language itself when there is
    /// one; "Kwoma" when there is not; "Unknown language (xyz)" for a tag no table knows.
    pub fn label(&self) -> String {
        match self.native {
            Some(n) if self.is_known() => format!("{} — {n}", self.english_label()),
            _ => self.english_label(),
        }
    }

    /// Whether `query` (any case) finds this language: part of any of its names, or one of
    /// its codes exactly. "Bengali", "Bangla", "বাংলা" and "ben" all find `bn`.
    pub fn matches(&self, query: &str) -> bool {
        self.match_rank(query).is_some()
    }

    /// How well `query` finds this language, best first: 0 for one of its codes (`ben`), 1
    /// for the start of a word of a name ("beng"), 2 for elsewhere in a name; `None` when it
    /// does not. An empty query finds every language, at 0.
    pub fn match_rank(&self, query: &str) -> Option<u8> {
        let q = query.trim().to_lowercase();
        if q.is_empty() || self.codes.contains(&q) {
            return Some(0);
        }
        let word_start = |n: &str| {
            n.match_indices(q.as_str()).any(|(i, _)| {
                n[..i]
                    .chars()
                    .next_back()
                    .is_none_or(|c| !c.is_alphanumeric())
            })
        };
        if self.lower_names.iter().any(|n| word_start(n)) {
            Some(1)
        } else if self.lower_names.iter().any(|n| n.contains(&q)) {
            Some(2)
        } else {
            None
        }
    }
}

/// One language row of `cldr-names.tsv`.
struct CldrLanguage {
    english: &'static str,
    native: Option<&'static str>,
    also: Vec<&'static str>,
}

/// One row of `iso-639-3.tsv`.
struct IsoCode {
    id: &'static str,
    part2b: Option<&'static str>,
    part1: Option<&'static str>,
    name: &'static str,
}

struct Tables {
    languages: HashMap<&'static str, CldrLanguage>,
    scripts: HashMap<&'static str, &'static str>,
    regions: HashMap<&'static str, &'static str>,
    /// Each language's usual script (`bn` → `Beng`), from CLDR's likely subtags.
    default_scripts: HashMap<&'static str, &'static str>,
    iso: Vec<IsoCode>,
    /// Every ISO 639-1, 639-2/B and 639-3 code, to its row in `iso`.
    iso_codes: HashMap<&'static str, usize>,
}

fn tables() -> &'static Tables {
    static TABLES: OnceLock<Tables> = OnceLock::new();
    TABLES.get_or_init(|| Tables::parse(CLDR_NAMES, ISO_639_3))
}

fn nonempty(s: Option<&'static str>) -> Option<&'static str> {
    s.filter(|s| !s.is_empty())
}

impl Tables {
    fn parse(cldr: &'static str, iso: &'static str) -> Tables {
        let mut t = Tables {
            languages: HashMap::new(),
            scripts: HashMap::new(),
            regions: HashMap::new(),
            default_scripts: HashMap::new(),
            iso: Vec::new(),
            iso_codes: HashMap::new(),
        };
        for line in cldr.lines().filter(|l| !l.starts_with('#')) {
            let f: Vec<&'static str> = line.split('\t').collect();
            match f[..] {
                ["L", code, english, ..] => {
                    let also = nonempty(f.get(4).copied())
                        .map(|a| a.split('|').collect())
                        .unwrap_or_default();
                    t.languages.insert(
                        code,
                        CldrLanguage {
                            english,
                            native: nonempty(f.get(3).copied()),
                            also,
                        },
                    );
                }
                ["S", code, english] => {
                    t.scripts.insert(code, english);
                }
                ["R", code, english] => {
                    t.regions.insert(code, english);
                }
                ["D", code, script] => {
                    t.default_scripts.insert(code, script);
                }
                _ => {}
            }
        }
        let mut retired: Vec<(&'static str, &'static str, &'static str)> = Vec::new();
        for line in iso.lines().filter(|l| !l.starts_with('#')) {
            let f: Vec<&'static str> = line.split('\t').collect();
            let (id, part2b, part1, name) = match f[..] {
                [id, part2b, part1, name] => (id, part2b, part1, name),
                [id, _, _, name, change_to] => {
                    retired.push((id, name, change_to));
                    continue;
                }
                _ => continue,
            };
            let row = IsoCode {
                id,
                part2b: nonempty(Some(part2b)),
                part1: nonempty(Some(part1)),
                name,
            };
            let i = t.iso.len();
            for code in [Some(id), row.part2b, row.part1].into_iter().flatten() {
                t.iso_codes.entry(code).or_insert(i);
            }
            t.iso.push(row);
        }
        // A retired code reads as the code that replaced it, else (split) under its old name.
        for (id, name, change_to) in retired {
            if let Some(&i) = t.iso_codes.get(change_to) {
                t.iso_codes.entry(id).or_insert(i);
            } else {
                t.iso_codes.entry(id).or_insert(t.iso.len());
                t.iso.push(IsoCode {
                    id,
                    part2b: None,
                    part1: None,
                    name,
                });
            }
        }
        t
    }

    fn name(&self, tag: &str) -> LanguageName {
        let subtags = canonical_subtags(tag);
        let lower = subtags.join("-").to_lowercase();
        let iso = subtags
            .first()
            .and_then(|l| self.iso_codes.get(l.as_str()))
            .map(|&i| &self.iso[i]);
        // The language subtag as CLDR keys it: ISO 639-1 where there is one.
        let primary = iso
            .map(|r| r.part1.unwrap_or(r.id).to_string())
            .or_else(|| subtags.first().cloned())
            .unwrap_or_default();
        let mut codes = vec![lower.clone()];
        if let Some(r) = iso {
            codes.extend(
                [Some(r.id), r.part2b, r.part1]
                    .into_iter()
                    .flatten()
                    .map(str::to_string),
            );
        }
        codes.push(primary.clone());
        let mut seen = std::collections::HashSet::new();
        codes.retain(|c| seen.insert(c.clone()));
        let mut also: Vec<&'static str> = Vec::new();
        let base = self.languages.get(primary.as_str());
        if let Some(b) = base {
            also.extend(b.also.iter().copied());
        }
        // The ISO 639-3 reference name, when CLDR names the language otherwise ("Bengali").
        if let (Some(r), Some(b)) = (iso, base)
            && !b.english.eq_ignore_ascii_case(r.name)
        {
            also.push(r.name);
        }
        let rest: Vec<&str> = subtags.iter().skip(1).map(String::as_str).collect();
        // The longest CLDR entry the tag starts with (`zh-Hant` of `zh-Hant-HK`), and how many
        // of `rest` it covers.
        let entry = |rest: &[&str]| {
            (1..=rest.len()).rev().find_map(|k| {
                let id = std::iter::once(primary.as_str())
                    .chain(rest[..k].iter().copied())
                    .collect::<Vec<_>>()
                    .join("-");
                self.languages.get(id.as_str()).map(|l| (l, k))
            })
        };
        let mut rest = rest;
        // The script the language is usually written in names nothing: `bn-Beng-IN` reads as
        // `bn-IN`, `kk-Cyrl` as `kk`; unless CLDR has a name of its own for the language in
        // it ("Simplified Chinese", not "Chinese (Simplified)", for `zh-Hans`).
        if let Some(&default) = self.default_scripts.get(primary.as_str()) {
            let own_name = self
                .languages
                .get(format!("{primary}-{default}").as_str())
                .zip(base)
                .zip(self.scripts.get(default))
                .is_some_and(|((l, b), script)| l.english != format!("{} ({script})", b.english));
            if !own_name {
                rest.retain(|s| *s != default);
            }
        }
        let found = entry(&rest);
        let key = std::iter::once(primary.as_str())
            .chain(rest.iter().copied())
            .collect::<Vec<_>>()
            .join("-");
        let (english, native) = if let Some((_, n)) = SWORD_TAGS.iter().find(|(t, _)| *t == lower) {
            (Some((*n).to_string()), base.and_then(|b| b.native))
        } else {
            let (named, covered) = match found {
                Some((l, k)) => {
                    also.extend(l.also.iter().copied());
                    (Some(l.english), k)
                }
                None => (base.map(|b| b.english).or(iso.map(|r| r.name)), 0),
            };
            let left = &rest[covered..];
            let parts: Vec<&str> = left
                .iter()
                .map(|s| {
                    let named = if is_script(s) {
                        self.scripts.get(s)
                    } else if is_region(s) {
                        self.regions.get(s)
                    } else {
                        None
                    };
                    named.copied().unwrap_or(s)
                })
                .collect();
            let english = named.map(|e| match e.strip_suffix(')') {
                _ if parts.is_empty() => e.to_string(),
                // CLDR's "Serbian (Latin)" in Serbia is "Serbian (Latin, Serbia)".
                Some(open) if covered > 0 => format!("{open}, {})", parts.join(", ")),
                _ => format!("{e} ({})", parts.join(", ")),
            });
            // A script changes how the language is written; its own name may not hold.
            let native = match found {
                Some((l, _)) => l.native,
                None => base.and_then(|b| b.native),
            }
            .filter(|_| !left.iter().any(|s| is_script(s)));
            (english, native)
        };
        let mut seen = std::collections::HashSet::new();
        also.retain(|a| seen.insert(*a));
        let lower_names = english
            .iter()
            .map(String::as_str)
            .chain(native)
            .chain(also.iter().copied())
            .map(str::to_lowercase)
            .collect();
        LanguageName {
            tag: tag.to_string(),
            english,
            native,
            also,
            codes,
            primary,
            key,
            lower_names,
        }
    }
}

fn is_script(s: &str) -> bool {
    s.len() == 4 && s.chars().all(|c| c.is_ascii_alphabetic())
}

fn is_region(s: &str) -> bool {
    (s.len() == 2 && s.chars().all(|c| c.is_ascii_alphabetic()))
        || (s.len() == 3 && s.chars().all(|c| c.is_ascii_digit()))
}

/// The tag's subtags in BCP 47's preferred case: `zh`, `Hant`, `TW`, `variant`.
fn canonical_subtags(tag: &str) -> Vec<String> {
    tag.trim()
        .split(['-', '_'])
        .filter(|s| !s.is_empty())
        .enumerate()
        .map(|(i, s)| {
            if i > 0 && is_script(s) {
                let mut c = s.chars();
                c.next()
                    .map(|f| f.to_ascii_uppercase().to_string() + &c.as_str().to_lowercase())
                    .unwrap_or_default()
            } else if i > 0 && is_region(s) {
                s.to_ascii_uppercase()
            } else {
                s.to_ascii_lowercase()
            }
        })
        .collect()
}

/// The English name of the language of `tag` (its first subtag) when a table knows it: CLDR's,
/// else the ISO 639-3 reference name. For labels that group a language's tags.
pub fn english_name(tag: &str) -> Option<&'static str> {
    let t = tables();
    let first = canonical_subtags(tag).into_iter().next()?;
    let iso = t.iso_codes.get(first.as_str()).map(|&i| &t.iso[i]);
    let primary = iso.map_or(first.as_str(), |r| r.part1.unwrap_or(r.id));
    t.languages
        .get(primary)
        .map(|l| l.english)
        .or(iso.map(|r| r.name))
}
